import sys; sys.path.insert(0, '/tmp/analysis')
import numpy as np, pandas as pd
from bins import raw, residual, BASE_LO

SENSORS = {
    "CORE":         ["CORE_FLUX_01", "CORE_FUEL_01", "CORE_ROD_01", "CORE_EXIT_01"],
    "PRIMARY_LOOP": ["PRIMARY_PRES_01", "PRIMARY_TEMP_01", "PRIMARY_FLOW_01", "PRIMARY_LEVEL_01"],
    "STEAM_GEN":    ["STEAM_FEED_01", "STEAM_DELTA_01", "STEAM_TEMP_01", "STEAM_PRES_01"],
    "COOLING":      ["COOLING_TEMP_01", "COOLING_HEAT_01", "COOLING_FLOW_01", "COOLING_PRES_01"],
    "TURBINE":      ["TURB_SPEED_01", "TURB_VIB_01", "TURB_BEAR_01", "TURB_OUTPUT_01"],
}
# first corrective action per subsystem (UTC) -- analysis window must end before it
ACTION = {"TURBINE": "2024-01-16 02:52", "COOLING": "2024-01-16 03:35",
          "STEAM_GEN": "2024-01-16 05:08", "PRIMARY_LOOP": "2024-01-16 08:12", "CORE": "2024-01-16 15:56"}

def mins(ts):
    return np.asarray((pd.to_datetime(ts) - BASE_LO) / pd.Timedelta(minutes=1), dtype=float)

def pooled(sids, lo, hi):
    out = []
    for s in sids:
        r = residual(raw[raw.sensor_id == s])
        r = r[(r.t_phys >= lo) & (r.t_phys < hi)]
        out.append((mins(r.t_phys.values), r.r.values))
    return out

def onset(data, lo_m, hi_m, p):
    best = (np.inf, None)
    for T in np.arange(lo_m, hi_m, 0.5):
        sse = 0.0
        for t, y in data:
            x = np.clip(t - T, 0, None) / 60.0          # hours since onset
            X = np.column_stack([np.ones(len(t)), x ** p])
            c, *_ = np.linalg.lstsq(X, y, rcond=None)
            sse += ((y - X @ c) ** 2).sum()
        if sse < best[0]:
            best = (sse, T)
    return best[1]

def clock(m):
    return (BASE_LO + pd.Timedelta(minutes=float(m))).strftime("%m-%d %H:%M")

if __name__ == "__main__":
    LO = pd.Timestamp("2024-01-15 22:00")
    lo_m = float(mins(LO))
    table = {}
    for p in (0.5, 1.0, 1.5, 2.0):
        row = {}
        for sub, sids in SENSORS.items():
            hi = min(pd.Timestamp(ACTION[sub]), pd.Timestamp("2024-01-16 02:30")) - pd.Timedelta(minutes=0)
            data = pooled(sids, LO, hi)
            hi_m = float(mins(hi)) - 40          # keep the search grid inside the usable window
            row[sub] = onset(data, lo_m + 30, hi_m, p)
        table[p] = row
        order = sorted(row, key=row.get)
        print(f"p={p:<4}", "  ".join(f"{s}={clock(row[s])}" for s in order), "->", " < ".join(order))
EOF
cd /tmp/analysis && python3 -I shape.py

